CREATE TABLE "competition" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(250) UNIQUE NOT NULL,
    "description" text,
    "discipline_id" bigint NOT NULL,
    "competition_type_id" bigint NOT NULL,
    "competition_level_id" bigint NOT NULL,
    "format" varchar(20) NOT NULL,
    "start_at" timestamptz NOT NULL,
    "end_at" timestamptz NOT NULL,
    "registration_starts_at" timestamptz NOT NULL,
    "registration_ends_at" timestamptz NOT NULL,
    "venue_address" text,
    "online_url" text,
    "created_by" bigint NOT NULL,
    "status" varchar(30) NOT NULL DEFAULT 'draft',
    "calendar_plan_id" bigint,
    "calendar_plan_number" varchar(100),
    "regulation_url" text,
    "updated_at" timestamptz,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "competition_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_competition_type_id_fkey"
        FOREIGN KEY ("competition_type_id") REFERENCES "competition_type" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_competition_level_id_fkey"
        FOREIGN KEY ("competition_level_id") REFERENCES "competition_level" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_created_by_fkey"
        FOREIGN KEY ("created_by") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_calendar_plan_id_fkey"
        FOREIGN KEY ("calendar_plan_id") REFERENCES "calendar_plan" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "competition_event" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "competition_id" bigint NOT NULL,
    "discipline_id" bigint NOT NULL,
    "age_group_id" bigint,
    "protocol_url" text,
    CONSTRAINT "competition_event_competition_id_fkey"
        FOREIGN KEY ("competition_id") REFERENCES "competition" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_event_discipline_id_fkey"
        FOREIGN KEY ("discipline_id") REFERENCES "discipline" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_event_age_group_id_fkey"
        FOREIGN KEY ("age_group_id") REFERENCES "age_group" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "competition_judge" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "competition_id" bigint NOT NULL,
    "judge_user_id" bigint NOT NULL,
    "position_id" bigint NOT NULL,
    "appointed_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "competition_judge_competition_id_fkey"
        FOREIGN KEY ("competition_id") REFERENCES "competition" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_judge_judge_user_id_fkey"
        FOREIGN KEY ("judge_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_judge_position_id_fkey"
        FOREIGN KEY ("position_id") REFERENCES "judge_position" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

COMMENT ON COLUMN "competition"."format" IS 'offline, online, mixed';
COMMENT ON COLUMN "competition"."status" IS 'draft — черновик; under_review — на проверке; published — опубликовано; registration_open — регистрация открыта; registration_closed — регистрация закрыта; ongoing — проводится; results_pending — подведение итогов; completed — завершено';
